(7651537, 1245055, 24983, '<td valign="top">well it shows really well how you can change the whole mood of a shot</td>', 'well it shows really well how you can change the whole mood of a shot', '2020-01-24 02:40:22.000000', NULL, 1),
(7651569, 1245118, 16912, '<td valign="top">Love the lighting here.</td>', 'Love the lighting here.', '2020-01-24 09:49:33.000000', NULL, 1),
(7651576, 1245106, 86447, '<td valign="top">Very cool idea and well done!<br/> <br/> <br/>My pick for the Blue.</td>', 'Very cool idea and well done!  My pick for the Blue.', '2020-01-24 12:33:25.000000', NULL, 1),
(7651578, 1245058, 252551, '<td valign="top">Big improvement in colours &amp; skin smoothing.  Maybe her forehead could be slightly less smoothed ?</td>', 'Big improvement in colours & skin smoothing.  Maybe her forehead could be slightly less smoothed ?', '2020-01-24 13:31:28.000000', NULL, 1),
(7651622, 1245101, 3306, '<td valign="top">I thought you would remove that beard in photoshop and let us see what the real Bear looks like!</td>', 'I thought you would remove that beard in photoshop and let us see what the real Bear looks like!', '2020-01-25 17:47:39.000000', NULL, 1),
(7651623, 1244980, 3306, '<td valign="top">Very nicely done. My favorite of the challenge.</td>', 'Very nicely done. My favorite of the challenge.', '2020-01-25 17:49:29.000000', NULL, 1),
(7651624, 1245055, 3306, '<td valign="top">I like your control of the lighting in post processing. A ribbon for sure.</td>', 'I like your control of the lighting in post processing. A ribbon for sure.', '2020-01-25 17:51:41.000000', NULL, 1),
(7651625, 1245058, 3306, '<td valign="top">Good job bringing out the natural colors. Nice pose and attractive model.</td>', 'Good job bringing out the natural colors. Nice pose and attractive model.', '2020-01-25 17:53:50.000000', NULL, 1),
(7651626, 1245106, 3306, '<td valign="top">Very creative and interesting portrait. One of my ribbon choices.</td>', 'Very creative and interesting portrait. One of my ribbon choices.', '2020-01-25 17:55:13.000000', NULL, 1),
(7651627, 1245118, 3306, '<td valign="top">Well done Mark. I like the contrasting between the color and B&amp;W images and the transitional lighting. I symmetry is outstanding right down to the ripples in the shirt.</td>', 'Well done Mark. I like the contrasting between the color and B&W images and the transitional lighting. I symmetry is outstanding right down to the ripples in the shirt.', '2020-01-25 18:01:21.000000', NULL, 1),
(7651784, 1245117, 16632, '<td valign="top">Aaah, I wish you''d left the small bruise on his mouth ;] ... Nice one, though. I also like you flipped the image.</td>', 'Aaah, I wish you''d left the small bruise on his mouth ;] ... Nice one, though. I also like you flipped the image.', '2020-01-28 07:50:31.000000', NULL, 1),
(7651864, 1244980, 16632, '<td valign="top">Good photo, though I would probably choose the unedited version :) ...</td>', 'Good photo, though I would probably choose the unedited version :) ...', '2020-01-29 02:35:58.000000', NULL, 1),
