(7651963, 1244835, 42733, '<td valign="top">My favorite in the challenge.</td>', 'My favorite in the challenge.', '2020-01-29 13:49:33.000000', NULL, 1),
(7651964, 1244939, 42733, '<td valign="top">My pick for red in this challenge. Really seems to meet the spirit of the challenge to show an edit.</td>', 'My pick for red in this challenge. Really seems to meet the spirit of the challenge to show an edit.', '2020-01-29 13:49:58.000000', NULL, 1),
