(7652085, 1245106, 135744, '<td valign="top">Love the creative touch. My top score - will be surprised if this doesn''t get the blue</td>', 'Love the creative touch. My top score - will be surprised if this doesn''t get the blue', '2020-01-30 13:03:10.000000', NULL, 1),
(7652213, 1245109, 3306, '<td valign="top">Nice. I see some subtle changes that make this a realistic edit</td>', 'Nice. I see some subtle changes that make this a realistic edit', '2020-01-30 19:45:09.000000', NULL, 1),
(7652214, 1244979, 3306, '<td valign="top">Im not sure I see much difference here aside from making the image lighter.</td>', 'Im not sure I see much difference here aside from making the image lighter.', '2020-01-30 19:47:03.000000', NULL, 1),
(7652215, 1245111, 3306, '<td valign="top">I wouldnt want to get any closer to that cow!</td>', 'I wouldnt want to get any closer to that cow!', '2020-01-30 19:47:58.000000', NULL, 1),
(7652216, 1245110, 3306, '<td valign="top">Sweet.</td>', 'Sweet.', '2020-01-30 19:48:13.000000', NULL, 1),
(7652218, 1244835, 3306, '<td valign="top">Not crazy about the background but I like the way you enhanced his eyes and sharpened the image.</td>', 'Not crazy about the background but I like the way you enhanced his eyes and sharpened the image.', '2020-01-30 19:49:59.000000', NULL, 1),
(7652219, 1245115, 3306, '<td valign="top">A creative and unique take on the challenge.</td>', 'A creative and unique take on the challenge.', '2020-01-30 19:50:47.000000', NULL, 1),
(7652220, 1245116, 3306, '<td valign="top">This is interesting. I can see differences in the top and bottom images but Im not sure which is the before and which is the after. Im guessing that the bottom is the after since the background is darker and the skin tone seems slightly lighter.</td>', 'This is interesting. I can see differences in the top and bottom images but Im not sure which is the before and which is the after. Im guessing that the bottom is the after since the background is darker and the skin tone seems slightly lighter.', '2020-01-30 19:55:14.000000', NULL, 1),
(7652222, 1245095, 97225, '<td valign="top">This is the entry which shows the greatest improvement via processing of the original. Great job! I hope it earns you a ribbon. 10 from me.</td>', 'This is the entry which shows the greatest improvement via processing of the original. Great job! I hope it earns you a ribbon. 10 from me.', '2020-01-30 20:43:06.000000', NULL, 1),
(7652224, 1245110, 97225, '<td valign="top">Very sweet!</td>', 'Very sweet!', '2020-01-30 20:51:28.000000', NULL, 1),
(7652225, 1244980, 97225, '<td valign="top">Both versions are beautiful and bring to mind Renaissance painting. The ''cosmetic surgery'' on the girl on the right (of the picture) was probably not necessary. Top 3.</td>', 'Both versions are beautiful and bring to mind Renaissance painting. The ''cosmetic surgery'' on the girl on the right (of the picture) was probably not necessary. Top 3.', '2020-01-30 20:52:26.000000', NULL, 1),
(7652226, 1245055, 97225, '<td valign="top">Nice portrait to begin with. Great portrait with the processing. Top 3.</td>', 'Nice portrait to begin with. Great portrait with the processing. Top 3.', '2020-01-30 20:53:46.000000', NULL, 1),
(7652227, 1245117, 124815, '<td valign="top">Hi Tibi! You were a bit harsh with yourself - must be your alter ego - but nice portrait</td>', 'Hi Tibi! You were a bit harsh with yourself - must be your alter ego - but nice portrait', '2020-01-30 20:57:09.000000', NULL, 1),
(7652228, 1245106, 124815, '<td valign="top">Interestingly done</td>', 'Interestingly done', '2020-01-30 20:58:52.000000', NULL, 1),
(7652229, 1244980, 124815, '<td valign="top">A nod to the Renaissance and great use of the border</td>', 'A nod to the Renaissance and great use of the border', '2020-01-30 21:00:26.000000', NULL, 1),
(7652232, 1245095, 3306, '<td valign="top">Good treatment of the background and well done believable editing of the subject.</td>', 'Good treatment of the background and well done believable editing of the subject.', '2020-01-30 21:44:25.000000', NULL, 1),
(7652233, 1244921, 3306, '<td valign="top">I like the way you have brought the color out in her eyes. I wish her pupils were not so dilated. Skin tones are a little light and I liked the original reddish tone of her hair.  None the less I like the overall result.</td>', 'I like the way you have brought the color out in her eyes. I wish her pupils were not so dilated. Skin tones are a little light and I liked the original reddish tone of her hair.  None the less I like the overall result.', '2020-01-30 21:49:58.000000', NULL, 1),
(7652235, 1245098, 3306, '<td valign="top">Desaturating the background while bringing out the color in the subject and her horn is an effective way of enhancing your model. Making her corneas and teeth a little lighter and sharpening her eyes would also help to bring attention to her attractive face.</td>', 'Desaturating the background while bringing out the color in the subject and her horn is an effective way of enhancing your model. Making her corneas and teeth a little lighter and sharpening her eyes would also help to bring attention to her attractive face.', '2020-01-30 21:56:14.000000', NULL, 1),
(7652236, 1245117, 3306, '<td valign="top">Its interesting that by increasing the clarity and sharpness you have actually brought out the overall texture of his face which has the effect of making him look more intense.</td>', 'Its interesting that by increasing the clarity and sharpness you have actually brought out the overall texture of his face which has the effect of making him look more intense.', '2020-01-30 21:59:34.000000', NULL, 1),
(7652237, 1245119, 3306, '<td valign="top">A handsome fish indeed!</td>', 'A handsome fish indeed!', '2020-01-30 22:00:14.000000', NULL, 1),
(7652238, 1245101, 173844, '<td valign="top">The shadows on his face thrown by the hat are greatly diminished.  Is it realistic?  Don''t know.  Aside from that, the switch from color to black and white soups up the image tremendously.  He is now an aviator, contrasty contrails and clouds echoing the brightness of the face and beard.  It''s now an heroic image, celebrating a life of adventure, outside in the elements.<br/>Personal favorite of the challenge.</td>', 'The shadows on his face thrown by the hat are greatly diminished.  Is it realistic?  Don''t know.  Aside from that, the switch from color to black and white soups up the image tremendously.  He is now an aviator, contrasty contrails and clouds echoing the brightness of the face and beard.  It''s now an heroic image, celebrating a life of adventure, outside in the elements.Personal favorite of the challenge.', '2020-01-30 22:11:46.000000', NULL, 1),
(7652246, 1245055, 124815, '<td valign="top">From life as is to mysticism. Well done</td>', 'From life as is to mysticism. Well done', '2020-01-31 00:09:30.000000', NULL, 0),
